sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cutoff;
uniform float softness;
uniform float mode;
layout(color) uniform half4 matteColor;
uniform float solidify;
uniform float invert;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float k = smoothstep(cutoff - softness, cutoff + softness + 0.0001, c.a);
    if (invert > 0.5) k = 1.0 - k;
    float na = mix(c.a * k, k, solidify);
    float4 r = float4(unp(c) * na, na);
    if (mode > 0.5 && mode < 1.5) r = float4(float3(matteColor.rgb) * na, na);
    else if (mode > 1.5) r = float4(float3(k), 1.0);
    return fin(c, r, opacity);
}
